LC_ALL=C awk '
FILENAME==ARGV[1] {
  lines++;
  bytes += length($0) + 1;
  next
}
FILENAME==ARGV[2] {
  # store checksums lines
  cs[++csi] = $0;
  next
}
FILENAME==ARGV[3] {
  # try to extract Size:<number> anywhere in the content
  if(match($0, /Size:([0-9]+)/, m)) metasize = m[1];
  next
}
FILENAME==ARGV[4] {
  index_lines++;
  next
}
END {
  print "Consistency Report for /root/matrix.txt and temp_workspace artifacts";
  print "---------------------------------------------------------------";
  print "Lines in matrix.normal:", (lines?lines:0);
  print "Bytes in matrix.normal:", (bytes?bytes:0);
  if(metasize) {
    print "Metadata reported size:", metasize;
    if(metasize == bytes) print "Size_match: OK";
    else print "Size_match: MISMATCH (metadata vs matrix.normal)";
  } else {
    print "Metadata reported size: MISSING or unparsable";
  }
  if(csi>=2) {
    split(cs[1], a, " ");
    split(cs[2], b, " ");
    print "Original checksum:", a[1], "file:", a[2];
    print "Backup checksum:  ", b[1], "file:", b[2];
    if(a[1] == b[1]) print "Backup_match: OK";
    else print "Backup_match: MISMATCH";
  } else {
    print "Checksums: missing or incomplete in checksums.txt";
  }
  print "Line_index entries:", index_lines;
  if(index_lines && lines) {
    if(index_lines == lines) print "Index_coverage: OK";
    else print "Index_coverage: MISMATCH (index entries vs lines)";
  } else {
    print "Index_coverage: insufficient data to compare";
  }
  print "Prepared artifacts:";
  print " - temp_workspace/metadata.txt";
  print " - temp_workspace/permissions.txt";
  print " - temp_workspace/backup_info.txt";
  print " - temp_workspace/checksums.txt";
  print " - temp_workspace/matrix.normal";
  print " - temp_workspace/sample_lines.txt";
  print " - temp_workspace/line_index.txt";
  print " - temp_workspace/consistency_report.txt";
  print "---------------------------------------------------------------";
  if(lines) print "Note: For final line count of /root/matrix.txt, refer to the count produced separately.";
}' temp_workspace/matrix.normal temp_workspace/checksums.txt temp_workspace/metadata.txt temp_workspace/line_index.txt > temp_workspace/consistency_report.txt
