awk '{
v=$0;
gsub(/^[ \t\r\n]+|[ \t\r\n]+$/, "", v);
if (v == "") { print "conversion: "; print "error: empty value"; exit }
if (v ~ /^[+-]?[0-9]+$/) {
  gsub(/^\+/, "", v);
  if (v ~ /^-/) { s=substr(v,2); sub(/^0+/, "", s); if (s=="") s="0"; print "conversion: -" s }
  else { s=v; sub(/^0+/, "", s); if (s=="") s="0"; print "conversion: " s }
  print "error: none"
} else if (v ~ /^[+-]?[0-9]*\.[0-9]+$/) {
  sign="";
